import sys
from collections import deque

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(0)
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    e = int(next(it))

    # Build adjacency list for left nodes (1 to n)
    adj = [[] for _ in range(n + 1)]

    for _ in range(e):
        u = int(next(it))
        v = int(next(it))
        adj[u].append(v)

    # Hopcroft-Karp for maximum bipartite matching
    # pair_u[u] = which node in V is paired with u in U (0 means unpaired)
    # pair_v[v] = which node in U is paired with v in V (0 means unpaired)
    pair_u = [0] * (n + 1)
    pair_v = [0] * (m + 1)

    def bfs():
        """BFS to find shortest augmenting paths, returns distance to furthest unpaired node in U"""
        dist = [float('inf')] * (n + 1)
        queue = deque()
        for u in range(1, n + 1):
            if pair_u[u] == 0:
                dist[u] = 0
                queue.append(u)

        result = float('inf')
        while queue:
            u = queue.popleft()
            if dist[u] < result:
                for v in adj[u]:
                    if pair_v[v] == 0:
                        result = dist[u] + 1
                    elif dist[pair_v[v]] == float('inf'):
                        dist[pair_v[v]] = dist[u] + 1
                        queue.append(pair_v[v])
        return result

    def dfs(u, d):
        """DFS to find augmenting path of exact distance d"""
        if u == 0:
            return True
        if d + 1 < dist[u]:
            dist[u] = d + 1
            for v in adj[u]:
                if pair_v[v] == 0 or (dist[pair_v[v]] == d + 2 and dfs(pair_v[v], d + 2)):
                    pair_u[u] = v
                    pair_v[v] = u
                    return True
        return False

    matching = 0
    dist = [0] * (n + 1)

    while True:
        d = bfs()
        if d == float('inf'):
            break
        for u in range(1, n + 1):
            if pair_u[u] == 0:
                if dfs(u, 0):
                    matching += 1

    print(matching)

if __name__ == "__main__":
    main()
